#include "credentials_policy.h"
#include <assert.h>
int main(void){uint8_t b[16]={0},old[16]={0};char text[33];assert(credential_parse("01:02-03 04 05 06 07 08",b,8));credential_hex(b,8,text);assert(!strcmp(text,"0102030405060708"));assert(credential_parse("00112233445566778899aabbccddeeff",b,16));credential_hex(b,16,text);assert(!strcmp(text,"00112233445566778899AABBCCDDEEFF"));memcpy(old,b,16);assert(!credential_parse("00112233445566778899aabbccddeef",b,16));assert(!memcmp(b,old,16));assert(!credential_parse("00112233445566778899aabbccddeefg",b,16));assert(!credential_parse("00112233445566778899aabbccddeeff00",b,16));assert(!credential_parse(NULL,b,8));tracker_credentials_t a={.version=1},c=a;assert(credential_equal(&a,&c));c.app_key[15]=1;assert(!credential_equal(&a,&c));return 0;}
